    const rules = cssRules(allCss());
    const serifRe = /font-family\s*:\s*(var\(--font-serif\)|[^;]*(?<!sans-)\bserif\b)/i;
    for (const p of PILLARS) {
      const candidates = within(main)
        .getAllByText(p.title)
